// Pattern A: registry aggregation + budget state merge
const registryRows = $input.all().map(i => i.json).filter(r => r && r.actor_slug);
const apifyRegistry = {};
const apifyInputShapes = {};
for (const r of registryRows) {
  apifyRegistry[r.task_category] = r.actor_slug;
  if (r.required_input_shape) apifyInputShapes[r.task_category] = r.required_input_shape;
}

const budgetRaw = $('Fetch Budget').first().json;
const rows = Array.isArray(budgetRaw) ? budgetRaw : [budgetRaw];
const state = rows[0] || { monthly_limit_usd: 200, month_spend_usd: 0, today_spend_usd: 0, kill_switches: {} };
const ks = typeof state.kill_switches === 'string' ? JSON.parse(state.kill_switches) : (state.kill_switches || {});
const limit = state.monthly_limit_usd || 200;
const budgetOk = (state.today_spend_usd || 0) <= limit / 28;

return [{ json: { 
  monthlyLimit: limit,
  monthSpend: state.month_spend_usd || 0,
  todaySpend: state.today_spend_usd || 0,
  killSwitches: ks,
  budgetOk,
  apifyRegistry,
  apifyInputShapes
} }];

// === Agent Plan (CURRENT PLAN block) ===
let plan = {};
let plan_stale = false;
try {
  const planRaw = $('Fetch Maya Plan').first().json;
  const planArr = Array.isArray(planRaw) ? planRaw : (planRaw.data ? (typeof planRaw.data === 'string' ? JSON.parse(planRaw.data) : planRaw.data) : [planRaw]);
  plan = (Array.isArray(planArr) ? planArr[0] : planArr) || {};
} catch(e) { plan = {}; }
const STALE_HOURS = 72;
if (!plan.last_rendered_at) {
  plan_stale = true;
} else {
  const ageHours = (Date.now() - new Date(plan.last_rendered_at).getTime()) / 3600000;
  plan_stale = ageHours > STALE_HOURS;
}
const planBlock = (plan.current_phase || plan.objective) ? (
  'CURRENT PLAN:\n' +
  (plan.current_phase  ? `Phase: ${plan.current_phase}\n` : '') +
  (plan.objective      ? `Objective: ${plan.objective}\n` : '') +
  (plan.next_milestone ? `Next milestone: ${plan.next_milestone}\n` : '') +
  (plan.blockers       ? `Blockers: ${plan.blockers}\n` : '') +
  (plan.doc_link       ? `Plan doc: ${plan.doc_link}\n` : '') +
  (plan.status         ? `Status: ${plan.status}\n` : '') +
  '\n'
) : '';

const ks = $('Budget Guard').first().json.killSwitches;
const budgetOk = $('Budget Guard').first().json.budgetOk;

let brief = '';
try {
  const r = $('Fetch Maya Brief').first().json;
  const rows = Array.isArray(r) ? r : (r.data ? JSON.parse(r.data) : []);
  if (rows[0] && rows[0].brief_content) brief = rows[0].brief_content;
} catch(e) {}

let voiceRules = '';
try {
  const r = $('Fetch Voice Rules').first().json;
  const rows = Array.isArray(r) ? r : (r.data ? JSON.parse(r.data) : []);
  if (rows[0] && rows[0].value) voiceRules = rows[0].value;
} catch(e) {}

let rules = [];
try {
  const raw = $('Fetch Opt Rules').first().json;
  const rows = Array.isArray(raw) ? raw : (raw.data ? JSON.parse(raw.data) : [raw]);
  if (Array.isArray(rows) && rows[0] && rows[0].details) {
    const d = typeof rows[0].details === 'string' ? JSON.parse(rows[0].details) : rows[0].details;
    rules = d.rules || [];
  }
} catch(e) {}
const rulesText = rules.length > 0 ? rules.map(r => '- ' + r.rule).join('\n') : 'No optimization rules yet.';

// Parse product_health data
let productHealth = {};
try {
  const ph = $('Read Product Health').first().json;
  const phRows = Array.isArray(ph) ? ph : [ph];
  for (const row of phRows) {
    if (row && row.app_name) {
      productHealth[row.app_name] = {
        http_status: row.http_status,
        response_time_ms: row.response_time_ms,
        system_status: row.system_status,
        days_since_last_commit: row.days_since_last_commit,
        open_issues: row.open_issues,
        checked_at: row.checked_at
      };
    }
  }
} catch(e) {}

let identityPrefix = '';
if (brief) identityPrefix += '# You Are Maya\n' + brief + '\n\n';
if (planBlock) identityPrefix += planBlock;
if (voiceRules) identityPrefix += '# Voice Rules (Krish)\n' + voiceRules + '\n\n';

return [{ json: { optimizationRules: rulesText, killSwitches: ks, budgetOk, identityPrefix, productHealth, plan_stale } }];

const prev = $input.first().json;
const ks = prev.killSwitches || {};
const ph = prev.productHealth || {};
const day = new Date().getDay();
// Retired 2026-07-06 (Krish directive): gutted, merciless, onalert removed from the rotation.
