// targeting wired into B2C Prep, and plinth (b2b) has not been verified against B2B Prep's
// per-product config. Wire those configs first, then restore full-time/plinth here.
const schedule = { 1: { product: 'mm-ctrl', type: 'b2b' }, 2: { product: 'fractionl-circle', type: 'b2b' }, 3: { product: 'none', type: 'skip' }, 4: { product: 'none', type: 'skip' }, 5: { product: 'mindmaker', type: 'b2b' }, 6: { product: 'none', type: 'skip' }, 0: { product: 'none', type: 'sunday' } };
const entry = schedule[day] || schedule[0];

// Check if today's product is down
