if (ks.apollo || ks.instantly) return [{ json: { skipped: true, msg: '\ud83d\udeab <b>Maya B2B</b> [<code>' + d.product + '</code>]\n\nSkipped: kill switch active for Apollo/Instantly' } }];
const icps = { 'mm-ctrl': { t: ['Founder','CEO'], l: 'CTRL' }, 'fractionl-circle': { t: ['Fractional CMO','Fractional CFO','Fractional CTO'], l: 'Circle' }, 'mindmaker': { t: ['Chief Strategy','Head of AI','Chief AI Officer'], l: 'Mindmaker' } };
const icp = icps[d.product] || icps.mindmaker;
const wk = Math.ceil((new Date() - new Date(new Date().getFullYear(),0,1)) / 604800000);
