// Read competitor changes from Supabase competitor_health
// Emits an Apify-shaped payload so Comp Finalize downstream works unchanged
const d = $input.first().json;
if (d.productDown) return [{ json: { msg: '🚫 <b>Maya Competitive</b>\nSkipped: product health check shows service down/5xx', audit: JSON.stringify({ actor: 'maya', event_type: 'competitive-intel-skipped', display_message: 'Maya Competitive: skipped, product health check failing', details: '{"reason":"product_down"}' }) } }];

const ks = d.killSwitches || {};
if (ks['comp-scan']) return [{ json: { msg: '🚫 <b>Maya Competitive</b>\nSkipped: comp-scan kill switch active', audit: JSON.stringify({ actor: 'maya', event_type: 'competitive-intel-skipped', display_message: 'Maya Competitive: skipped, comp-scan kill switch active', details: '{}' }) } }];

const SUPA_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/competitor_health';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

// Pull today's changes only (last 36h window to cover scheduling drift)
const since = new Date(Date.now() - 36*60*60*1000).toISOString();
function buildQuery(params) {
  const parts = [];
  for (const k of Object.keys(params)) {
    parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(params[k]));
  }
  return parts.join('&');
}
const qp = buildQuery({
  select: 'competitor_url,competitor_name,product,title,meta_description,change_summary,checked_at',
  change_detected: 'eq.true',
  checked_at: 'gte.' + since,
  order: 'checked_at.desc',
  limit: '50'
});

let items = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: SUPA_URL + '?' + qp,
    headers: { apikey: SUPA_KEY, Authorization: 'Bearer ' + SUPA_KEY },
    json: true
  });
  items = Array.isArray(resp) ? resp : [];
} catch (e) {
  return [{ json: { msg: '🚫 <b>Maya Competitive</b>\nSkipped: competitor_health fetch failed: ' + (e.message || 'unknown'), audit: JSON.stringify({ actor: 'maya', event_type: 'competitive-intel-error', display_message: 'Maya Competitive: competitor_health fetch failed', details: JSON.stringify({ error: String(e.message || e) }) }) } }];
}

// Emit Apify-shaped payload so Comp Finalize works without change
return [{ json: { data: { items }, items } }];

const raw = $input.first().json;
const p = $('Comp Prep').first().json;
if (p.msg) { const a = p.audit ? JSON.parse(p.audit) : { actor: 'maya', event_type: 'competitive-intel-skipped', details: '{}' }; a.display_message = p.msg; return [{ json: { msg: p.msg, audit: JSON.stringify(a) } }]; }
const changes = raw?.data?.items || raw?.items || [];
const hasError = raw?.error || raw?.data?.error;
if (hasError) return [{ json: { msg: 'Maya Comp: Apify error (check actor)', audit: JSON.stringify({ actor: 'maya', event_type: 'competitive-intel-error', display_message: 'Maya Comp: Apify error (check actor)', details: JSON.stringify({ error: String(hasError.message || hasError) }) }) } }];
return [{ json: { msg: 'Maya Comp: ' + changes.length + ' changes detected', audit: JSON.stringify({ actor: 'maya', event_type: 'competitive-change-detected', display_message: 'Maya Comp: ' + changes.length + ' competitor changes detected.', details: JSON.stringify({ changes: changes.length }) }) } }];

// Fetch unprocessed HARO queries from Supabase (3-day window, status=new)
const d = $input.first().json;
if (d.productDown) return [{ json: { msg: '🚫 <b>Maya Earned Media</b>\nSkipped: product health check shows service down/5xx', audit: JSON.stringify({ actor: 'maya', event_type: 'earned-media-skipped', display_message: 'Maya Earned Media: skipped, product health check failing', details: '{"reason":"product_down"}' }) } }];

const ks = d.killSwitches || {};
if (ks.haro) return [{ json: { msg: '🚫 <b>Maya Earned Media</b>\nSkipped: HARO kill switch active', audit: JSON.stringify({ actor: 'maya', event_type: 'earned-media-skipped', display_message: 'Maya Earned Media: skipped, HARO kill switch active', details: '{}' }) } }];

const SUPA_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/haro_queries';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

// Fetch new queries from last 3 days
const threeDaysAgo = new Date(Date.now() - 3*24*60*60*1000).toISOString();
function buildQuery(params) {
  const parts = [];
  for (const k of Object.keys(params)) {
    parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(params[k]));
  }
  return parts.join('&');
}
const qp = buildQuery({
  select: 'id,journalist_name,outlet,category,query_text,deadline,requirements,email_to_pitch,received_at',
  status: 'eq.new',
  received_at: 'gte.' + threeDaysAgo,
  order: 'received_at.desc',
  limit: '50'
});

let items = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: SUPA_URL + '?' + qp,
    headers: { apikey: SUPA_KEY, Authorization: 'Bearer ' + SUPA_KEY },
    json: true
  });
