// Maya-specific: parse the task JSON string, tag weekly_goal_id via heuristic match, re-serialize.
const goalsRaw = $('Read Weekly Goals').first().json;
const goalsArr = Array.isArray(goalsRaw) ? goalsRaw : (goalsRaw.data || [goalsRaw]);
const goals = goalsArr.filter(g => g && g.id);

function pickGoalId(text) {
  if (!text || !goals.length) return null;
  const hay = String(text).toLowerCase();
  let best = null, bestLen = 0;
  for (const g of goals) {
    for (const c of [g.title, g.current].filter(Boolean)) {
      for (const tok of String(c).toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 4)) {
        if (hay.includes(tok) && tok.length > bestLen) { best = g.id; bestLen = tok.length; }
      }
    }
  }
  return best;
}

return $input.all().map(item => {
  const j = item.json || {};
  let taskObj = null;
  try {
    if (typeof j.task === 'string') taskObj = JSON.parse(j.task);
    else if (j.task && typeof j.task === 'object') taskObj = j.task;
  } catch(e) {}
  if (!taskObj) return { json: j };
  const gid = pickGoalId((taskObj.title || '') + ' ' + (taskObj.description || ''));
  taskObj.weekly_goal_id = gid;
  return { json: { ...j, task: JSON.stringify(taskObj), weekly_goal_id: gid } };
});
